package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

type TierTable struct {
	TierEntry struct {
		TierLimit decimal.Decimal
		TierRate  decimal.Decimal
	}
}

var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var tierLimits [5]decimal.Decimal
var tierRates [5]decimal.Decimal

var salesFileReader *bufio.Scanner
var salesFile *os.File
var currentSalesRec SalesRec
var inputDone bool

func format_ZZZ_ZZ9_99(v decimal.Decimal) string {
	// PIC ZZZ,ZZ9.99 width 10
	return formatEdited(v, "ZZZ,ZZ9.99")
}

func format_ZZZ_ZZZ_ZZ9_99(v decimal.Decimal) string {
	// PIC ZZZ,ZZZ,ZZ9.99 width 14
	return formatEdited(v, "ZZZ,ZZZ,ZZ9.99")
}

func format_9_99(v decimal.Decimal) string {
	return formatEdited(v, "9.99")
}

func formatEdited(v decimal.Decimal, pic string) string {
	// Determine integer digits and scale from picture
	// pic contains '.'; part after '.' are 9's (scale)
	dotIdx := strings.Index(pic, ".")
	intPic := pic
	scale := 0
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		scale = len(pic) - dotIdx - 1
	}
	// intPic includes Z , 9
	// integer width = len(intPic)
	// Need value rounded/truncated already before calling; but ensure scale
	// Negative values not expected; handle sign as per COBOL: would need separate handling, ignore.

	// Truncate/round already done; we format absolute value
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	// Ensure scale exactly
	v = v.Truncate(int32(scale))

	// Get integer part digits
	// Use string representation with fixed scale
	s := v.StringFixed(int32(scale)) // e.g. "1234.56"
	parts := strings.SplitN(s, ".", 2)
	intStr := parts[0]
	fracStr := ""
	if scale > 0 {
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", scale)
		}
		// pad frac
		if len(fracStr) < scale {
			fracStr = fracStr + strings.Repeat("0", scale-len(fracStr))
		}
		if len(fracStr) > scale {
			fracStr = fracStr[:scale]
		}
	}
	// Handle high-order digit overflow: keep only low-order digits that fit
	// Number of digit positions in intPic = count of Z and 9
	digitCount := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			digitCount++
		}
	}
	// intStr may be longer than digitCount -> drop high-order
	if len(intStr) > digitCount {
		intStr = intStr[len(intStr)-digitCount:]
	}
	// Pad intStr on left with zeros to digitCount
	if len(intStr) < digitCount {
		intStr = strings.Repeat("0", digitCount-len(intStr)) + intStr
	}
	// Now map digits onto intPic from right to left
	// intPicChars is array, we fill result same length
	n := len(intPic)
	res := make([]byte, n)
	digitIdx := len(intStr) - 1 // index in intStr
	for i := n - 1; i >= 0; i-- {
		ch := intPic[i]
		if ch == 'Z' || ch == '9' {
			res[i] = intStr[digitIdx]
			digitIdx--
		} else if ch == ',' {
			res[i] = ','
		} else {
			res[i] = byte(ch)
		}
	}
	// Z suppression: leading zeros replaced with spaces, commas in suppressed zone become spaces
	// Find first non-suppressed position: suppression applies to leading Z's until we hit a non-zero digit or a '9' position
	// Standard: scan from left; if char is Z and digit is '0' and we haven't yet encountered a non-zero, replace with space
	// Commas that are in the suppressed region (i.e., all digits to left are suppressed) become spaces
	suppressing := true
	for i := 0; i < n; i++ {
		ch := intPic[i]
		if ch == 'Z' {
			if suppressing && res[i] == '0' {
				res[i] = ' '
			} else {
				suppressing = false
			}
		} else if ch == '9' {
			suppressing = false
		} else if ch == ',' {
			// comma becomes space if still suppressing (i.e., no significant digit to left has appeared)
			if suppressing {
				// check if any significant digit to left? Actually suppression continues; need to look ahead if suppression still active
				// The comma is considered part of suppressed zone if all digits to its left are suppressed
				// Our suppressing flag indicates that
				res[i] = ' '
			}
		}
	}
	// Special COBOL rule: if value is zero, all Z positions are spaces, but at least one zero before decimal remains (the rightmost 9)
	// Our logic already leaves the '9' as '0'

	intPart := string(res)
	if scale > 0 {
		intPart = intPart + "." + fracStr
	}
	if neg {
		// For edited pictures without sign, COBOL would show sign separately; not needed here
		// Just prefix minus if needed (not in this program)
		intPart = "-" + intPart
	}
	return intPart
}

func formatCount(v int64) string {
	// PIC 9(3) zero padded width 3
	s := fmt.Sprintf("%03d", v)
	if len(s) > 3 {
		s = s[len(s)-3:]
	}
	return s
}

func formatTier(v int64) string {
	s := fmt.Sprintf("%01d", v)
	if len(s) > 1 {
		s = s[len(s)-1:]
	}
	return s
}

func main() {
	MAINPARA()
}

func MAINPARA() {
	INITPARA()
	// OPEN INPUT SALES-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		f = nil
		salesFile = nil
		salesFileReader = nil
	} else {
		salesFile = f
		salesFileReader = bufio.NewScanner(f)
	}
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	if salesFile != nil {
		salesFile.Close()
	}
	SUMMARYPARA()
}

func INITPARA() {
	tierLimits[1] = decimal.NewFromFloat(1000.00)
	tierRates[1] = decimal.NewFromFloat(2.50)
	tierLimits[2] = decimal.NewFromFloat(5000.00)
	tierRates[2] = decimal.NewFromFloat(4.00)
	tierLimits[3] = decimal.NewFromFloat(20000.00)
	tierRates[3] = decimal.NewFromFloat(5.50)
	tierLimits[4] = decimal.RequireFromString("999999.99")
	tierRates[4] = decimal.NewFromFloat(7.25)
}

func READPARA() {
	if salesFileReader == nil {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	if !salesFileReader.Scan() {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	line := salesFileReader.Text()
	// pad with spaces to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	}
	if len(line) > 12 {
		line = line[:12]
	}
	srId := line[0:4]
	srSalesRaw := line[4:12]
	// PIC 9(6)V99 digits only, implied decimal 2
	srSalesRaw = strings.TrimSpace(srSalesRaw)
	if srSalesRaw == "" {
		srSalesRaw = "0"
	}
	// Remove any non-digit just in case, keep digits
	// But spec says digits only
	n, _ := decimal.NewFromString(srSalesRaw)
	// srSalesRaw is integer representing value*100
	// Use New with exponent -2
	d := decimal.New(n.IntPart(), -2)
	currentSalesRec.SrId = srId
	currentSalesRec.SrSales = d
	WsEofFlag = "N"
	inputDone = false
}

func PROCESSPARA() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && !(WsTier > 0); WsIdx++ {
		if currentSalesRec.SrSales.Cmp(tierLimits[WsIdx]) <= 0 {
			WsTier = WsIdx
		}
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE (WS-TIER) / 100
	rate := tierRates[WsTier]
	prod := currentSalesRec.SrSales.Mul(rate)
	quot := prod.Shift(-2)
	// ROUNDED to scale 2
	WsComm = quot.Round(2)
	// handle overflow truncation to 9(6)V99: keep low-order digits - apply via truncate to fit? Just keep value; formatting will truncate high digits but storage should also
	// Simulate storage truncation: width 8 digits (6+2)
	WsComm = truncateToDigits(WsComm, 8, 2)

	WsTotal = WsTotal.Add(WsComm)
	WsTotal = truncateToDigits(WsTotal, 11, 2)

	WsCount++

	WsSalesEd = format_ZZZ_ZZ9_99(currentSalesRec.SrSales)
	WsRateEd = format_9_99(rate)
	WsCommEd = format_ZZZ_ZZ9_99(WsComm)

	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	// SR-ID is X(4) exactly
	fmt.Printf("%s T%s %s %s%% %s\n", currentSalesRec.SrId, formatTier(WsTier), WsSalesEd, WsRateEd, WsCommEd)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = format_ZZZ_ZZZ_ZZ9_99(WsTotal)
	fmt.Printf("REPS: %s TOTAL: %s\n", formatCount(WsCount), WsTotalEd)
}

func truncateToDigits(v decimal.Decimal, totalDigits int, scale int32) decimal.Decimal {
	neg := v.IsNegative()
	if neg {
		v = v.Neg()
	}
	// Truncate to scale already? For storage, value is kept with scale; high-order digits dropped
	// totalDigits includes integer+fraction digits
	intDigits := totalDigits - int(scale)
	s := v.StringFixed(scale)
	parts := strings.SplitN(s, ".", 2)
	intPart := parts[0]
	fracPart := ""
	if scale > 0 && len(parts) > 1 {
		fracPart = parts[1]
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
		// rebuild
		if scale > 0 {
			s = intPart + "." + fracPart
		} else {
			s = intPart
		}
		v2, _ := decimal.NewFromString(s)
		if neg {
			v2 = v2.Neg()
		}
		return v2
	}
	if neg {
		v = v.Neg()
	}
	return v
}
